import{_ as i,l as r,o as a,c as n,v as o,p as c,x as d,d as s,i as l,S as p}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"命名管道","description":"","frontmatter":{"title":"命名管道","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/named-pipe.md","filePath":"cs/named-pipe.md","lastUpdated":1789023840000}'),h={name:"cs/named-pipe.md"};function m(_,e,E,f,F,u){const t=r("Mermaid");return a(),n("div",null,[e[1]||(e[1]=o('<h1 id="命名管道" tabindex="-1">命名管道 <a class="header-anchor" href="#命名管道" aria-label="Permalink to &quot;命名管道&quot;">​</a></h1><div class="epigraph"><p>FIFO 把管道这种内核缓冲挂进目录：无亲缘进程也可以用路径打开同一条字节流。</p><footer>—— 据 POSIX FIFO；Stevens, UNIX Network Programming；Bach 整理</footer></div><p><a href="/cs/ipc-pipe">上一课</a>的匿名管道只靠继承描述符。<a href="/cs/inode-dir">inode 与目录</a> 已能表示特殊文件。<a href="/cs/file-table">文件表</a> 对 FIFO 与普通文件共用 fd。缺口是 <strong>命名</strong>：<code>mkfifo</code> 创建目录项，两端 <code>open</code> 会合，缓冲仍在内核，不经磁盘文件内容。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>无亲缘的两个作业要对齐字节流，匿名 <code>pipe()</code> 做不到。若改用真正文件，要自己做轮询与截断。FIFO：inode 类型是管道，没有数据块指针；<code>open</code> 读端/写端在对方出现前可阻塞（除非 <code>O_NONBLOCK</code>）。缺口不是新的调度睡眠，而是路径与会合语义。权限用上一单元的模式位。</p><p>本课不把 System V <code>msgget</code> 当 FIFO 的另一种名字讲完。</p><p><span class="marginnote">两端都关闭后缓冲丢弃。名字仍在目录里，可再打开。这与普通文件「内容还在盘上」不同。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>mkfifo(path, mode)</code>：VFS 创建 FIFO inode。进程 A <code>open</code> 读、B <code>open</code> 写，内核把它们接到同一环形缓冲，此后 <code>read</code>/<code>write</code> 与匿名管道相同，包括 <code>SIGPIPE</code>。<a href="/cs/path-lookup">路径查找</a> 与 dcache 照常。不要把 FIFO 写到交换区当文件页——数据只在内存缓冲。</p>',9)),(a(),c(p,null,{default:d(()=>[l(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20NAME%5B%22%E7%9B%AE%E5%BD%95%E4%B8%AD%E7%9A%84%20FIFO%22%5D%20--%3E%20OPEN%5B%22%E4%B8%A4%E7%AB%AF%20open%20%E4%BC%9A%E5%90%88%22%5D%0A%20%20OPEN%20--%3E%20BUF%5B%22%E5%86%85%E6%A0%B8%E7%8E%AF%E5%BD%A2%E7%BC%93%E5%86%B2%22%5D%0A%20%20BUF%20--%3E%20RW%5B%22read%2Fwrite%20%E5%90%8C%E5%8C%BF%E5%90%8D%E7%AE%A1%E9%81%93%22%5D%0A"})]),fallback:d(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>命名管道把 IPC 接到文件系统命名空间，让 shell 重定向与无关进程共用同一抽象。它仍是单向字节流，无消息边界（除非用户自己定）。下一课 Unix 域套接字会补双向、数据报与传描述符。本课只补「有路径的管道」。</p><p>阻塞会合把调度再请进来：写者未出现则读者睡。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 Linux 特有的 <code>O_DIRECT</code> 对 FIFO 的限制表。不保证原子写长度与匿名管道完全相同的每一个边界情况，教学上同一 POSIX 规则。下一课需要记录边界、双向、以及凭据。</p><p>后课默认：无亲缘进程可用路径会合字节流。更丰富的本地套接字，下一课 Unix 域。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>FIFO 是挂在目录上的管道，open 会合。</li><li>数据在内核缓冲，不在文件块。</li><li>双向与传 fd 是 Unix 域套接字的缺口。</li><li>出处：POSIX FIFO；Stevens, <em>UNP</em>；Bach, <em>UNIX</em>。</li></ul>',8))])}const I=i(h,[["render",m]]);export{B as __pageData,I as default};
